    "heroSubtitle": "வகுப்பாசிரியர் வகுப்பை உருவாக்கும்போது, அந்த வகுப்பின் மாணவர்களுக்கு மட்டும் அவர்களின் பாடங்கள், ஆசிரியர்கள் மற்றும் நேரலை வகுப்புகள் தாய்மொழியில் காட்டப்படும்.",
    "heroBtnStudent": "மாணவர் உள்நுழைவு",
    "heroBtnTeacher": "ஆசிரியர் உள்நுழைவு",
    "feat1Title": "வகுப்பு வாரியான பாதுகாப்பு வடிகட்டுதல்",
