    "Good morning Class 6A students! Reminder that our Science Fair project topics must be submitted by this Friday. Please join today's 9:00 AM live session where I will demonstrate leaf stomata under microscope.": "காலை வணக்கம் 6A மாணவர்களே! அறிவியல் கண்காட்சி திட்டங்களை இந்த வெள்ளிக்கிழமைக்குள் சமர்ப்பிக்கவும். காலை 9 மணி நேரலை வகுப்பில் இணைக.",
