const LanguageContext = createContext();

export function LanguageProvider({ children }) {
  const [selectedLanguageCode, setSelectedLanguageCode] = useState(() => {
    return localStorage.getItem('grasp_language') || 'en';
  });

  useEffect(() => {
    localStorage.setItem('grasp_language', selectedLanguageCode);
  }, [selectedLanguageCode]);

  const changeLanguage = (langCode) => {
    const found = SUPPORTED_LANGUAGES.find(l => l.code.toLowerCase() === (langCode || '').toLowerCase());
    if (found) {
      setSelectedLanguageCode(found.code);
    }
  };

  const activeLangObj = SUPPORTED_LANGUAGES.find(l => l.code === selectedLanguageCode) || SUPPORTED_LANGUAGES[0];

  const t = (key, fallback = null) => {
    if (!key) return '';
    const langDict = TRANSLATIONS[selectedLanguageCode] || TRANSLATIONS['en'];
    if (langDict && langDict[key] !== undefined) {
      return langDict[key];
    }
    const dynDict = DYNAMIC_CONTENT_TRANSLATIONS[selectedLanguageCode];
    if (dynDict && dynDict[key] !== undefined) {
      return dynDict[key];
    }
    const localizedKey = localizeText(key, selectedLanguageCode);
    if (localizedKey && localizedKey !== key) {
      return localizedKey;
    }
    if (fallback !== null) {
      const localizedFallback = localizeText(fallback, selectedLanguageCode);
      return localizedFallback || fallback;
    }
    const enDict = TRANSLATIONS['en'];
    if (enDict && enDict[key] !== undefined) {
      if (selectedLanguageCode === 'en') return enDict[key];
      const localizedEn = localizeText(enDict[key], selectedLanguageCode);
      return localizedEn || enDict[key];
    }
    return key;
  };

  const localizeSubject = (subjectName) => {
    if (!subjectName) return "";
    const langMap = SUBJECT_TRANSLATIONS[selectedLanguageCode];
    if (langMap && langMap[subjectName]) {
      return langMap[subjectName];
    }
    for (const [eng, loc] of Object.entries(langMap || {})) {
      if (subjectName.toLowerCase().includes(eng.toLowerCase())) {
        return subjectName.replace(new RegExp(eng, 'i'), loc);
      }
    }
    return subjectName;
  };

  const localizeGrade = (gradeStr) => {
    if (!gradeStr) return "";
    const langMap = SUBJECT_TRANSLATIONS[selectedLanguageCode];
    if (langMap && langMap[gradeStr]) {
      return langMap[gradeStr];
    }
    return gradeStr;
  };

  // Localize any arbitrary text string (rooms, schedules, descriptions, etc.)
  const localizeText = (text, explicitLang = null) => {
    if (!text || typeof text !== 'string') return text || "";
    const targetLang = explicitLang || selectedLanguageCode || 'en';
    if (targetLang === 'en') return text;

    const dynDict = DYNAMIC_CONTENT_TRANSLATIONS[targetLang];
    if (dynDict && dynDict[text]) {
      return dynDict[text];
    }

    // Check partial phrases in dynamic content
    if (dynDict) {
      for (const [enPhrase, locPhrase] of Object.entries(dynDict)) {
        if (text === enPhrase) return locPhrase;
      }
    }

    // Localize schedule days pattern
    const dayMap = {
      mr: { Mon: 'सोम', Tue: 'मंगळ', Wed: 'बुध', Thu: 'गुरु', Fri: 'शुक्र', Sat: 'शनि', Sun: 'रवि', AM: 'स.', PM: 'दु.' },
      hi: { Mon: 'सोम', Tue: 'मंगल', Wed: 'बुध', Thu: 'गुरु', Fri: 'शुक्र', Sat: 'शनि', Sun: 'रवि', AM: 'पूर्वाह्न', PM: 'अपराह्न' },
      bn: { Mon: 'সোম', Tue: 'মঙ্গল', Wed: 'বুধ', Thu: 'বৃহস্পতি', Fri: 'শুক্র', Sat: 'শনি', Sun: 'রবি', AM: 'সকাল', PM: 'দুপুর' },
      pa: { Mon: 'ਸੋਮ', Tue: 'ਮੰਗਲ', Wed: 'ਬੁੱਧ', Thu: 'ਵੀਰ', Fri: 'ਸ਼ੁੱਕਰ', Sat: 'ਸ਼ਨੀ', Sun: 'ਐਤ', AM: 'ਸਵੇਰੇ', PM: 'ਦੁਪਹਿਰ' },
      ta: { Mon: 'திங்கள்', Tue: 'செவ்வாய்', Wed: 'புதன்', Thu: 'வியாழன்', Fri: 'வெள்ளி', Sat: 'சனி', Sun: 'ஞாயிறு', AM: 'காலை', PM: 'மதியம்' },
      te: { Mon: 'సోమ', Tue: 'మంగళ', Wed: 'బుధ', Thu: 'గురు', Fri: 'శుక్ర', Sat: 'శని', Sun: 'ఆది', AM: 'ఉదయం', PM: 'మధ్యాహ్నం' },
      kn: { Mon: 'ಸೋಮ', Tue: 'ಮಂಗಳ', Wed: 'ಬುಧ', Thu: 'ಗುರು', Fri: 'ಶುಕ್ರ', Sat: 'ಶನಿ', Sun: 'ಭಾನು', AM: 'ಬೆಳಗ್ಗೆ', PM: 'ಮಧ್ಯಾಹ್ನ' },
      gu: { Mon: 'સોમ', Tue: 'મંગળ', Wed: 'બુધ', Thu: 'ગુરુ', Fri: 'શુક્ર', Sat: 'શનિ', Sun: 'રવિ', AM: 'સવારે', PM: 'બપોરે' }
    };

    const currentDayMap = dayMap[targetLang];
    if (currentDayMap && (text.includes('•') || text.includes('AM') || text.includes('PM'))) {
      let localizedSchedule = text;
      for (const [enD, locD] of Object.entries(currentDayMap)) {
        localizedSchedule = localizedSchedule.replace(new RegExp(`\\b${enD}\\b`, 'g'), locD);
      }
      return localizedSchedule;
    }

    // Check subject translations
    const subjTrans = SUBJECT_TRANSLATIONS[targetLang];
    if (subjTrans && subjTrans[text]) {
      return subjTrans[text];
    }

    return text;
  };

  const getQuoteSegments = () => QUOTE_SEGMENTS[selectedLanguageCode] || QUOTE_SEGMENTS['en'];

  return (
    <LanguageContext.Provider value={{
      selectedLanguage: selectedLanguageCode,
      selectedLanguageCode,
      selectedLanguageName: activeLangObj.name,
      selectedLanguageNativeName: activeLangObj.nativeName,
      selectedLocale: activeLangObj.locale,
      currentLang: selectedLanguageCode,
      changeLanguage,
      t,
      localizeSubject,
      localizeGrade,
      localizeText,
      activeLangObj,
      supportedLanguages: SUPPORTED_LANGUAGES,
      quoteSegments: getQuoteSegments(),
      getQuoteSegments
    }}>
      {children}
    </LanguageContext.Provider>
  );
}

export const useLanguage = () => useContext(LanguageContext);
